  gorsel: "<svg viewBox=\"0 0 300 190\" role=\"img\" aria-label=\"Silindir açınımı; daire yarıçapı 5 cm, dikdörtgen 30 cm ve 3 cm\"><rect x=\"30\" y=\"72\" width=\"180\" height=\"18\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"60\" cy=\"42\" r=\"30\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"180\" cy=\"120\" r=\"30\" fill=\"var(--dolgu)\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"60\" y1=\"42\" x2=\"90\" y2=\"42\" stroke=\"var(--vurgu)\" stroke-width=\"2.5\"/><circle cx=\"60\" cy=\"42\" r=\"3.5\" fill=\"var(--vurgu)\"/><text x=\"98\" y=\"47\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"start\" font-weight=\"700\">r = 5 cm</text><text x=\"110\" y=\"112\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"middle\" font-weight=\"700\">30 cm</text><line x1=\"216\" y1=\"72\" x2=\"216\" y2=\"90\" stroke=\"var(--vurgu2)\" stroke-width=\"2\"/><line x1=\"211\" y1=\"72\" x2=\"221\" y2=\"72\" stroke=\"var(--vurgu2)\" stroke-width=\"2\"/><line x1=\"211\" y1=\"90\" x2=\"221\" y2=\"90\" stroke=\"var(--vurgu2)\" stroke-width=\"2\"/><text x=\"226\" y=\"86\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"start\" font-weight=\"700\">3 cm</text></svg>",
